def all_matchings(indices):
    if not indices:
        yield []
        return
    i=indices[0]
    for kk in range(1,len(indices)):
        j=indices[kk]
        rest=indices[1:kk]+indices[kk+1:]
        for tail in all_matchings(rest):
            yield [(i,j)]+tail

def evaluate_matching(sel):
    rels=list(fixed_edges)
    for i,j in sel:
        a,b=ends[i],ends[j]
        if a[0]==b[0]: return None
        rels.append((a[0],b[0],a[2],b[2]))
    adj=collections.defaultdict(list)
    for u,v,pu,pv in rels:
        d=(pu[0]-pv[0],pu[1]-pv[1])
        adj[u].append((v,d)); adj[v].append((u,(-d[0],-d[1])))
    ts={}
    for start in pieces:
        if start in ts: continue
        ts[start]=(0,0); stack=[start]
        while stack:
            u=stack.pop()
            for v,d in adj[u]:
                val=(ts[u][0]+d[0],ts[u][1]+d[1])
                if v in ts:
                    if ts[v]!=val:return None
                else: ts[v]=val;stack.append(v)
    todo=['D']; seen=set()
    while todo:
        u=todo.pop()
        if u in seen:continue
        seen.add(u);todo += [v for v,_ in adj[u] if v not in seen]
    if len(seen)!=len(pieces):return None
    norm=ts['C'];ts={k:(v[0]-norm[0],v[1]-norm[1]) for k,v in ts.items()}
    colmap={};pinmap={};bad=[]
    for name,p in pieces.items():
        dr,dc=ts[name]
        for r,c in p['cells']:
            pos=(r+dr,c+dc)
            if pos in colmap:bad.append(('color collision',pos,colmap[pos],name))
            colmap[pos]=name
        for (r,c),d0 in p['pins']:
            pos=(r+dr,c+dc)
            pinmap.setdefault(pos,[]).append(name)
    if set(colmap)&set(pinmap):bad.append(('color-pin',set(colmap)&set(pinmap)))
    allpos=list(colmap)+list(pinmap)
    bbox=(min(r for r,c in allpos),max(r for r,c in allpos),min(c for r,c in allpos),max(c for r,c in allpos))
    return ts,bad,bbox
